import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[65536];
        private int bufferPointer = 0, bytesRead = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
                if (bytesRead == -1) return -1;
            }
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = in.read(buffer, 0, buffer.length);
            bufferPointer = 0;
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
    }

    static class LongMinHeap {
        long[] data;
        int size;

        LongMinHeap(int capacity) {
            data = new long[capacity];
            size = 0;
        }

        void add(long val) {
            if (size == data.length) {
                data = Arrays.copyOf(data, data.length * 2);
            }
            int i = size++;
            while (i > 0) {
                int p = (i - 1) >>> 1;
                if (data[p] <= val) break;
                data[i] = data[p];
                i = p;
            }
            data[i] = val;
        }

        long poll() {
            long result = data[0];
            long val = data[--size];
            if (size > 0) {
                int i = 0;
                int half = size >>> 1;
                while (i < half) {
                    int left = (i << 1) + 1;
                    int right = left + 1;
                    int best = left;
                    if (right < size && data[right] < data[left]) {
                        best = right;
                    }
                    if (val <= data[best]) break;
                    data[i] = data[best];
                    i = best;
                }
                data[i] = val;
            }
            return result;
        }

        boolean isEmpty() {
            return size == 0;
        }
    }

    // Grafo
