            long top = pq.poll();
            int d = (int) (top >>> 32);
            int u = (int) (top & 0xFFFFFFFFL);

            if (d > dist[u]) continue;
            if (u == B) break;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                int w = weight[e];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.add((((long) dist[v]) << 32) | (v & 0xFFFFFFFFL));
                }
            }
        }

        if (dist[B] == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(dist[B]);
        }
    }

    static int findNodeId(long[] pairs, int l, int r, int u, int t, int N) {
        long target = (((long) u) << 32) | (t & 0xFFFFFFFFL);
        int low = l;
        int high = r - 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (pairs[mid] == target) {
                return N + 1 + mid;
            } else if (pairs[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }
